SELECT e.student_id::text AS student_id,e.slot AS slot,i.code AS code
FROM student_look_equipment e JOIN look_item i ON i.id=e.look_item_id
WHERE e.student_id IN #{id}

SELECT  FROM look_item

    status=#{status}
    AND slot=#{slot}

ORDER BY created_at DESC,id DESC OFFSET #{offset} LIMIT #{limit}

SELECT count(*) FROM look_item

    status=#{status}
    AND slot=#{slot}
